# -*- coding: utf-8 -*-
from taf.playwright.core.exceptions import SessionNotFound


class SessionStore(object):
    """Stores product facade/session instances by alias for Robot keyword calls."""

    DEFAULT_ALIAS = None

    def __init__(self):
        self._sessions = {}

    def add(self, session, alias=None):
        self._sessions[alias] = session
        return session

    def get(self, alias=None):
        if alias in self._sessions:
            return self._sessions[alias]
        raise SessionNotFound("No Playwright session found for alias {!r}".format(alias))

    def remove(self, alias=None):
        session = self.get(alias)
        del self._sessions[alias]
        return session

    def aliases(self):
        return list(self._sessions.keys())

    def close_all(self):
        errors = []
        for alias in list(self._sessions.keys()):
            session = self._sessions.pop(alias)
            try:
                session.close()
            except Exception as exc:  # pragma: no cover - defensive cleanup path
                errors.append((alias, exc))
        if errors:
            alias, exc = errors[0]
            raise type(exc)("Failed to close session {!r}: {}".format(alias, exc))
